@media(max-width:1200px){.desktop-ide .topbar{gap:4px}.desktop-ide .wb-menubar>button{padding:4px 6px}.desktop-ide #desktop-command-context{display:none}.desktop-ide #studio-hot-reload>span{display:none}.desktop-ide .studio-wordmark{display:none}.desktop-ide .workspace-control{max-width:170px}.desktop-ide .workspace-control select{width:158px}}
@media(max-width:950px){.desktop-ide .desktop-workspace{--dleft:0px!important;--dlresize:0px!important}.desktop-ide #dock-zone-left{position:absolute;width:min(280px,85vw);height:100%;left:27px;z-index:40;box-shadow:4px 0 20px #0007}.desktop-splitter[data-resize=left]{display:none}.desktop-ide #wb-command{width:175px;max-width:28vw;min-width:110px}.desktop-ide .brand strong{display:none}.desktop-ide .wb-menubar>button{font-size:11px;padding:4px 5px}.desktop-ide .studio-toolbar{gap:4px}.desktop-ide .studio-configuration select{min-width:105px!important;width:110px!important}.desktop-ide .workspace-control{max-width:155px}.desktop-ide #studio-inspector>span{display:none}.desktop-ide .dock-right-stack{font-size:11px}}
@media(max-width:700px){.desktop-ide .desktop-workspace{--dright:0px!important;--drresize:0px!important;grid-template-columns:var(--dlrail) 0 0 minmax(0,1fr) 0 0 var(--drrail)}.desktop-ide .dock-right-stack{position:absolute;width:min(302px,86vw);height:min(70%,calc(100% - min(var(--dock-bottom,190px),28vh) - 44px));right:0;top:0;z-index:35;box-shadow:-5px 0 25px #0007}.desktop-splitter[data-resize=right]{display:none}.desktop-ide .topbar{flex-wrap:nowrap;overflow:hidden;height:32px;min-height:32px}.desktop-ide .wb-menubar>button{display:none}.desktop-ide .wb-menubar>#wb-menu-file,.desktop-ide .wb-menubar>#wb-menu-view,.desktop-ide .wb-menubar>#wb-menu-window{display:block}.desktop-ide #wb-command{max-width:none;flex:1;width:auto;min-width:65px}.desktop-ide #wb-command kbd{display:none}.desktop-ide .studio-toolbar{height:37px;min-height:37px;padding:3px 5px}.desktop-ide .workspace-control{display:none}.desktop-ide #run{min-width:64px}.desktop-ide #run kbd{display:none}.desktop-ide .studio-debug-actions{gap:0}.desktop-ide .studio-debug-actions .studio-icon-action{width:22px}.desktop-ide #desktop-layout-preset,.desktop-ide #studio-hot-reload,.desktop-ide .studio-toolbar-divider,.desktop-ide .workspace-changes-button{display:none}.desktop-ide .studio-toolbar #studio-inspector{padding:3px;margin-left:auto}.desktop-ide .editor-pane{min-width:0}.desktop-ide .desktop-main[data-bottom=true]{grid-template-rows:minmax(100px,1fr) 5px min(var(--dock-bottom,190px),28vh)}.desktop-ide .dock-bottom-stack[data-split=true]{grid-template-columns:minmax(0,1fr)}.desktop-ide .dock-bottom-stack #dock-zone-bottom-right{position:absolute;bottom:0;right:0;width:min(302px,85vw);height:28vh;z-index:36}.desktop-ide .desktop-splitter[data-resize=bottomRatio]{display:none}.desktop-ide .status-right,.desktop-ide .studio-secure-label,.desktop-ide .desktop-build-status #build-summary{display:none}.desktop-ide .desktop-build-status{height:23px}.desktop-ide .desktop-build-status .live-label{display:none}.desktop-ide .desktop-document-modes .studio-perspectives button{font-size:10px;padding:2px 5px!important}.desktop-ide #desktop-show-toolbox{font-size:10px;padding:2px 4px}.desktop-ide #desktop-show-toolbox svg{display:none}}
@media(prefers-reduced-motion:reduce){.desktop-ide *{transition:none!important;animation:none!important}}

.symbols-policy{display:grid;grid-template-columns:repeat(2,minmax(180px,1fr));gap:10px;padding:10px}.symbols-policy>label{display:flex;flex-direction:column;gap:5px}.symbols-policy>label:has(input[type=checkbox]){flex-direction:row;align-items:center}.symbols-policy textarea{width:100%;max-width:100%;resize:vertical;border:1px solid var(--border);background:var(--editor);color:var(--text);font:11px/1.4 var(--mono);padding:6px}.symbols-policy details{grid-column:1/-1}.symbols-policy input[type=checkbox]{accent-color:var(--accent)}@media(max-width:800px){.symbols-policy{grid-template-columns:1fr}}
